import{_ as e,o as c,c as d,a5 as l}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"数据库连接池","description":"","frontmatter":{"title":"数据库连接池","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/01-JDBC/数据库连接池.md","filePath":"posts/java快速入门/第五部分：数据库/01-JDBC/数据库连接池.md"}'),t={name:"posts/java快速入门/第五部分：数据库/01-JDBC/数据库连接池.md"};function i(r,o,a,p,n,s){return c(),d("div",null,[...o[0]||(o[0]=[l('<div><p><strong>概念：</strong> 其实就是一个容器<code>(</code>集合<code>)</code>，存放数据库连接的容器。 当系统初始化好后，容器被创建，容器中会申请一些连接对象，当用户来访问数据库时，从容器中获取连接对象，用户访问完之后，会将连接对象归还给容器。</p><p><strong>好处：</strong><code>1.</code> 节约资源 <code>2.</code> 用户访问高效</p><p><strong>实现：</strong><code>1.</code> 标准接口：<code>DataSource javax.sql</code>包下的 方法： <code>*</code> 获取连接：</p><ul><li>getConnection()</li><li><ul><li></li></ul></li></ul><p>归还连接：<code>Connection.close()</code>。如果连接对象<code>Connection</code>是从连接池中获取的，那么调用<code>Connection.close()</code>方法，则不会再关闭连接了。而是归还连接 <code>2.</code> 一般我们不去实现它，有数据库厂商来实现 <code>1. C3P0</code>：数据库连接池技术 <code>2. Druid</code>：数据库连接池实现技术，由阿里巴巴提供的</p><p><code>C3P0</code><strong>：数据库连接池技术</strong> 步骤： <code>1.</code> 导入<code>jar</code>包 <code>(</code>两个<code>) c3p0-0.9.5.2.jar mchange-commons-java-0.2.12.jar</code> ， <code>*</code> 不要忘记导入数据库驱动<code>jar</code>包 <code>2.</code> 定义配置文件： <code>*</code> 名称： <code>c3p0.properties</code> 或者</p><ul><li>c3p0-config.xml</li><li><ul><li></li></ul></li></ul><p>路径：直接将文件放在<code>src</code>目录下即可。 <code>3.</code> 创建核心对象 数据库连接池对象</p><ul><li>ComboPooledDataSource</li><li><ol start="4"><li></li></ol></li></ul><p>获取连接： <code>getConnection</code></p><p><strong>代码：</strong><code>//1.</code>创建数据库连接池对象</p><p>DataSource ds = new ComboPooledDataSource(); //2. 获取连接对象 <code>Connection conn = ds.getConnection();</code></p><p><code>Druid</code>： 步骤： <code>1.</code> 导入<code>jar</code>包</p><ul><li>druid-1.0.9.jar</li><li><ol start="2"><li></li></ol></li></ul><p>定义配置文件： <code>*</code> 是<code>properties</code>形式的 <code>*</code> 可以叫任意名称，可以放在任意目录下 <code>3.</code> 加载配置文件。</p><ul><li>Properties</li><li><ol start="4"><li></li></ol></li></ul><p>获取数据库连接池对象，通过工厂来来获取：</p><ul><li>DruidDataSourceFactory</li><li><ol start="5"><li></li></ol></li></ul><p>获取连接：</p><ul><li>getConnection</li><li><ul><li></li></ul></li></ul><p>代码：</p><p>// 加载配置文件</p><p>Properties pro = new Properties(); InputStream is = DruidDemo.class.getClassLoader().getResourceAsStream(&quot;druid.properties&quot;); pro.load(is); // 获取连接池对象</p><p>DataSource ds = DruidDataSourceFactory.createDataSource(pro); // 获取连接 <code>Connection conn = ds.getConnection();</code></p><p><strong>定义工具类</strong><code>1.</code> 定义一个类</p><ul><li>JDBCUtils</li><li><ol start="2"><li></li></ol></li></ul><p>提供静态代码块加载配置文件，初始化连接池对象 <code>3.</code> 提供方法 <code>1.</code> 获取连接方法：通过数据库连接池获取连接 <code>2.</code> 释放资源 <code>3.</code> 获取连接池的方法</p><p><code>*</code> 代码：</p></div>',1)])])}const g=e(t,[["render",i]]);export{_ as __pageData,g as default};
